function HasCloseElements(numbers: array of real; threshold: real): boolean;
begin
  for var i := 0 to numbers.Length - 2 do
    for var j := i + 1 to numbers.Length - 1 do
      if Abs(numbers[i] - numbers[j]) < threshold then
      begin
        Result := True;
        exit;
      end;
  Result := False;
end;


function SeparateParenGroups(parenString: string): array of string;
begin
  parenString := parenString.Replace(' ', '');
  var stack := new Stack<string>;
  var current := new StringBuilder;
  var resultList := new List<string>;
  var balance := 0;

  for var i := 1 to parenString.Length do
  begin
    var ch := parenString[i];

    if ch = '(' then
      balance := balance + 1
    else if ch = ')' then
      balance := balance - 1;

    current.Append(ch);

    if balance = 0 then
    begin
      stack.Push(current.ToString);
      current := new StringBuilder;
    end;
  end;

  while stack.Count > 0 do
  begin
    resultList.Add(stack.Pop);
  end;

  Result := resultList.ToArray;
end;


