  var res := new List<integer>;
  for var i := 0 to numbers.Length - 1 do
  begin
    res.Add(numbers[i]);
    if i < numbers.Length - 1 then
      res.Add(delimiter);
  end;
  SetLength(Result, res.Count);
  for var i := 0 to res.Count - 1 do
    Result[i] := res[i];
end;


function ParseNestedParens(parenString: string): array of integer;
begin
  var stack := new Stack<integer>;
  var levels := new List<integer>;
  var currentLevel := 0;

  for var i := 1 to parenString.Length do
  begin
    if parenString[i] = '(' then
    begin
      currentLevel += 1;
      stack.Push(currentLevel);
      levels.Add(currentLevel);
    end
    else if parenString[i] = ')' then
    begin
      currentLevel -= 1;
      stack.Pop;
      var maxLevel := levels.Max;
      levels[levels.IndexOf(maxLevel)] := currentLevel;
    end;
  end;

  Result := levels.ToArray;
end;


