  var str := strValue.ToLower;
  if str.Length = 0 then
    exit('');
  var palindrome := '';
  for var i := 1 to str.Length do
  begin
    var prefix := str.Substring(0, i);
    var postfix := str.Substring(i);
    var reversedPostfix := new string(postfix.Reverse.ToArray);
    if prefix = reversedPostfix then
    begin
      palindrome := str + new string(prefix.Reverse.ToArray);
      break;
    end;
  end;
  Result := palindrome;
end;

