function Factorize(n: integer): array of integer;
begin
  var answer := new List<integer>;
  var tempN := n;

  for var i := 2 to Round(Sqrt(tempN)) do
  begin
    if tempN mod i = 0 then
    begin
      answer.Add(i);
      tempN := tempN div i;
    end
    else
      continue;
  end;

  if tempN > 1 then
    answer.Add(tempN);

  answer.Sort;
  Result := answer.ToArray;
end;


