function IsPrime(n: integer): boolean;
begin
  if n <= 1 then
    Result := False
  else if n <= 3 then
    Result := True
  else if (n mod 2 = 0) or (n mod 3 = 0) then
    Result := False
  else
  begin
    var i := 5;
    while i * i <= n do
    begin
      if (n mod i = 0) or (n mod (i + 2) = 0) then
      begin
        Result := False;
        exit;
      end;
      i += 6;
    end;
    Result := True;
  end;
end;

function Poly(xs : array of real; x : real): real;
{ Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n }
begin
  var _result := 0.0;
  for var i := 0 to xs.Length - 1 do
    _result := _result + xs[i] * Power(x, i);
  Result := _result;
end;
function FindZero(xs: array of real): real;
begin
  var n := xs.Length;
  if n = 0 then
  begin
    Result := 0.0;
    exit;
  end;
  if n mod 2 <> 0 then
  begin
    // Odd number of coefficients. Linear approximation.
    var y := new real[n + 1];
    for var i := 0 to n - 1 do
      y[i] := xs[i] / n;
    y[n] := 1;
    var eps := 1e-15;
    while true do
    begin
      var x := 0.0;
      for var i := 0 to n - 1 do
        x := x + y[i] * Power(x, i);
      var fx := Poly(y, x);
      if Abs(fx) < eps then
      begin
        Result := x;
        exit;
      end;
      // Polynomial not zero at x. Try next approximation point.
      y[0] := y[0] + 1e-15;
    end;
  end
  else
  begin
    // Even number of coefficients. Newton-Raphson.
    var y := new real[n + 1];
    for var i := 0 to n - 1 do
      y[i] := xs[i];
    y[n] := 0;
    var eps := 1e-15;
    var x := 1.0;
    while true do
    begin
      var fx := Poly(y, x);
      if Abs(fx) < eps then
      begin
        Result := x;
        exit;
      end;
      var df := Poly(y, 1.0);
      if Abs(df) < eps then
      begin
        // Polynomial has multiple zeros.
        // Use secant approximation.
        var x1 := x - y[0] * (x - x0) / (y[1] - y[0]);
        var fx1 := Poly(y, x1);
        if Abs(fx1) < eps then
        begin
          Result := x1;
          exit;
        end;
        y[0] := x;
        y[1] := x1;
        x := x1 + y[0] * (x1 - x);
        continue;
      end;
      // Polynomial not zero at x. Try next approximation point.
      x := x - y[0] * fx / df;
    end;
  end;
end;


function SortThird(l: array of integer): array of integer;
begin
  var thirds := new List<integer>;
  var others := new List<integer>;
  var othersCopy := new List<integer>(l);

  for var i := 0 to l.Length - 1 do
    if i mod 3 = 0 then
      thirds.Add(l[i])
    else
      others.Add(l[i]);

  thirds.Sort;
  var j := 0;

  for var i := 0 to l.Length - 1 do
    if i mod 3 = 0 then
      l[i] := thirds[j]
    else
    begin
      l[i] := othersCopy[j];
      j += 1;
    end;

  Result := l;
end;


