function CorrectBracketing(brackets: string): boolean;
begin
  var stack := new List<char>;
  foreach var ch in brackets do
  begin
    if ch = '<' then
      stack.Add(ch)
    else if ch = '>' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.RemoveAt(stack.Count - 1);
    end;
  end;
  Result := stack.Count = 0;
end;


