function AddElements(arr: array of integer; k: integer): integer;
begin
  var sum := 0;
  var limit := 100;
  var digits := new List<integer>;

  for var i := 0 to k - 1 do
  begin
    var num := arr[i];
    var numStr := num.ToString;

    for var j := 1 to numStr.Length do
      digits.Add(StrToInt(numStr[j]));
  end;

  digits.Sort;

  for var i := 0 to digits.Count - 1 do
  begin
    if digits[i] < limit then
    begin
      sum += digits[i];
      limit -= digits[i];
    end
    else
      break;
  end;

  Result := sum;
end;


function GetOddCollatz(n: integer): array of integer;
