  collatz.Add(1);
  var oddNums := new List<integer>;

  for var i := 2 to n do
  begin
    if i mod 2 <> 0 then
      oddNums.Add(i)
    else
    begin
      if i = 2 then
        collatz.Add(i)
      else
      begin
        var prev := collatz[collatz.Count - 1];
        collatz.Add(prev * 3 + 1);
      end;
    end;
  end;

  oddNums.AddRange(collatz);
  oddNums.Sort;
  Result := oddNums.ToArray;
end;


