function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  if n = 0 then
  begin
    Result := new integer[0];
    exit;
  end;
  var directions := |(0, 1), (1, 0), (0, -1), (-1, 0)|;
  var visited := new HashSet<(integer, integer)>;
  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((0, 0, 0) /* (x, y, steps) */);
  while queue.Count > 0 do
  begin
    var (x, y, steps) := queue.Dequeue;
    if steps = k then
    begin
      Result := new integer[k];
      var (idxX, idxY) := (x, y);
      for var idx := 0 to k - 1 do
      begin
        var (dx, dy) := directions[idx];
        while (dx <> 0) or (dy <> 0) do
        begin
          if (dx > 0) and (idxY < n - 1) and (grid[idxY + 1][idxX] < grid[idxY][idxX]) then
            idxY += 1
          else if (dy > 0) and (idxX < n - 1) and (grid[idxY][idxX + 1] < grid[idxY][idxX]) then
            idxX += 1
          else if (dx < 0) and (idxY > 0) and (grid[idxY - 1][idxX] < grid[idxY][idxX]) then
            idxY -= 1
          else if (dy < 0) and (idxX > 0) and (grid[idxY][idxX - 1] < grid[idxY][idxX]) then
            idxX -= 1;
          (dx, dy) := (dy, dx);
        end;
        Result[idx] := grid[idxY][idxX];
      end;
      exit;
    end;
    foreach var (dx, dy) in directions do
    begin
      var (newX, newY) := (x + dx, y + dy);
      if (newX >= 0) and (newX < n) and (newY >= 0) and (newY < n) and not visited.Contains((newX, newY)) then
      begin
        visited.Add((newX, newY));
        queue.Enqueue((newX, newY, steps + 1) /* (newX, newY, steps) */);
      end;
    end;
  end;
  Result := new integer[0];
end;

begin
end.




function Tri(n: integer): array of real;
begin
  var trib := new List<real>;
  trib.Add(3);

  for var i := 1 to n do
  begin
    if i mod 2 = 0 then
      trib.Add(1 + i div 2)
    else
    begin
      var prev1 := trib[trib.Count - 1];
      var prev2 := trib[trib.Count - 2];
      var prev3 := trib[trib.Count - 3];
      trib.Add(prev1 + prev2 + prev3);
    end;
  end;

  Result := trib.ToArray;
end;


function Digits(n: integer): integer;
begin
  var product := 1;
  var hasOdd := False;
  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 <> 0 then
    begin
      product := product * digit;
      hasOdd := True;
    end;
    n := n div 10;
  end;
  Result := if hasOdd then product else 0;
end;


function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];

    if (ch = '[') then
      stack.Push(ch)
    else if (ch = ']') then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;

      stack.Pop;
    end;
  end;

  Result := stack.Count = 0;
end;


