function CanArrange(arr: array of integer): integer;
begin
  var sorted := arr.ToArray;
  sorted.Sort;
  var n := sorted.Length;
  var ans := -1;

  for var i := 0 to n - 1 do
  begin
    if sorted[i] = i + 1 then
      ans := i
    else if sorted[i] > i + 1 then
    begin
      var temp := sorted[i];
      sorted[i] := i + 1;
      if sorted[temp - 1] = temp then
        ans := i;
    end;
  end;

  Result := ans;
end;


