function FixSpaces(text: string): string;
begin
  var sb := new StringBuilder;
  var prevChar := #0;
  var countSpaces := 0;

  for var i := 1 to text.Length do
  begin
    var ch := text[i];

    if ch = ' ' then
    begin
      countSpaces += 1;
      if prevChar <> ' ' then
      begin
        if countSpaces = 1 then
          sb.Append('_')
        else if countSpaces = 2 then
          sb.Append('-')
        else
          sb.Append('_');
      end;
    end
    else
    begin
      sb.Append(ch);
      prevChar := ch;
      countSpaces := 0;
    end;
  end;

  Result := sb.ToString;
end;


