function OrderByPoints(nums: array of integer): array of integer;
begin
  var sumDigits := new Dictionary<integer, integer>;
  for var i := 0 to nums.Length - 1 do
  begin
    var digitSum := 0;
    var n := Abs(nums[i]);
    while n > 0 do
    begin
      digitSum += n mod 10;
      n := n div 10;
    end;
    sumDigits[nums[i]] := digitSum;
  end;

  var list := nums.ToArray;
  list.Sort((a, b) -> 
  begin
    if sumDigits[a] <> sumDigits[b] then
      Result := sumDigits[a].Compare(sumDigits[b])
    else
      Result := list.IndexOf(b).Compare(list.IndexOf(a));
  end);

  Result := list;
end;

begin
end.




