function StrongestExtension(className: string; extensions: array of string): string;
begin
  var strength := new Dictionary<string, integer>;

  foreach var extension in extensions do
  begin
    var cap := 0;
    var sm := 0;

    for var i := 1 to extension.Length do
    begin
      if Char.IsUpper(extension[i]) then
        cap += 1;
      if Char.IsLower(extension[i]) then
        sm += 1;
    end;

    var st := cap - sm;
    if strength.ContainsKey(extension) then
      strength[extension] := st
    else
      strength.Add(extension, st);
  end;

  var maxSt := strength.Values.Max;
  var strongestExt := new List<string>;

  foreach var pair in strength do
    if pair.Value = maxSt then
      strongestExt.Add(pair.Key);

  Result := className + '.' + strongestExt[0];
end;


