    if Char.IsLetter(s[i]) then
    begin
      if flag then
        sb.Append(Char.ToUpper(s[i]))
      else
        sb.Append(Char.ToLower(s[i]));
      flag := not flag;
    end
    else
      sb.Append(s[i]);
  end;

  Result := sb.ToString;
end;


function StringToMd5(text: string): string;
