  var md5 := System.Security.Cryptography.MD5.Create;
  var bytes := Encoding.UTF8.GetBytes(text);
  var hash := md5.ComputeHash(bytes);

  Result := string.Join('', hash.Select(b -> b.ToString('x2')));
end;


